# mm_texmine.py - TexMine 2.1.1: AT mines laid inside objects (the "mine in the texture" glitch) on a Battlefield 2
# server - as a Multiplay ModManager module on the =FL= bus mm_flbus (ModManager 1.0 or later, Python 2.3 of BF2 1.5)
#
# What it does: every 0.1 s it looks at every AT mine. One that lies hidden in a watched object (Karkand's rails and
# level crossing, the rubble west of Square, the dock ramps, the planter, the pipes at Square, warehouses, wooden
# bridge heads - collision faces of 63 objects on 18 maps at the end of this file), went down through one of their
# faces, or lay still and then dropped straight down (the fall rule) is caught - a median 1.3 s after it was laid
# (it lies on the deck about 1 s before it sinks). MODE 3: the mine is lifted 1 m and falls back by itself, it stays
# the player's mine; in an object again after 3 lifts it is taken away under the map. A mine the game will not move
# at all (2.1.0) is set off where it lies after a countdown in the chat (3, 2, 1), WHOEVER is near - it can kill
# them (STUCK_BLAST 0: as 2.0.0, only when nobody at all is within 10 m). Claymores are not watched.
# A mine counts as hidden when at most 1 of 9 points on its top is uncovered; a point is covered by a face 1-50 cm
# over it (the site's rule), or (FLUSH, 1.6.0) by an upward face up to 2 cm UNDER the mine's top - the mine has sunk
# into the surface and its top is level with it (seen at the rail crossing where the ramp meets the road).
#
# Since 2.0.0 it runs on the bus mm_flbus: the bus's timer calls it, and the bus asks the game for the AT mines (by
# their template; every projectile every mm_flbus.TYPE_EVERY 5 s for new names) - once for all the =FL= scripts. What
# is done with a mine (lifted, taken under the map, set off) is texmine's own, as in 1.6.0: mines are handled unlike
# claymores and C4 (the game puts back a mine moved down, lets it move up).
#
# INSTALL
#   1. Copy this file and mm_flbus.py (1.0.1 or later) to <server folder>/admin/modules/
#   2. modmanager.con: the same line as for 1.x (modmanager.loadModule "mm_texmine"); mm_flbus needs no line of its own.
#      A line mm_texmine.TYPE_EVERY does nothing now: it is mm_flbus.TYPE_EVERY.
#   3. Restart the server (TexMine cannot be reloaded with "mm reloadModule").
#   4. texmine.log (server folder) should contain "texmine 2.1.1 loaded, on mm_flbus ... (mode 3: ..."; flbus.log
#      "texmine joined". If not, look in ModManager's log for "mm_texmine" (an error, or "requires ...").
# Do not run it together with texmine.py in admin/modules or admin/standard_admin.
#
# Settings: the values in the settings block below are the defaults; a line in modmanager.con overrides one, e.g.
#   mm_texmine.MODE 3            mm_texmine.LIFT_ASIDE 0        mm_texmine.FALL_RULE 1      mm_texmine.PASS_RULE 1
#   mm_texmine.KICK_AFTER 0      mm_texmine.SAY 1               mm_texmine.TEST_CHAT 0      mm_texmine.LOG_FILE "texmine.log"
#   mm_texmine.FLUSH 0.02        mm_texmine.FLUSH_ONLY ""      (FLUSH_ONLY "train_rail_crossing": that object only)
#   mm_texmine.STUCK_BLAST 1     mm_texmine.BLAST_COUNT 3       mm_texmine.BLAST_TRIES 5
#   mm_texmine.MSG_COUNT "..."   mm_texmine.MSG_COUNT_NOBODY "..."   mm_texmine.MSG_TICK "..."   mm_texmine.MSG_FAILED "..."
#   (a chat line: MSG_FAILED "" - not said; SAY 0 - no chat at all, the countdown still runs)
#   mm_texmine.TEST_CMDS 0       mm_texmine.TEST_ADMINS ""      mm_texmine.TEST_SPOT "-113.22 150.33 266.17"
#
# Test commands (TEST_CMDS 1 - for a test server only), typed in the chat by a living player; the answers go to the
# chat as "[TexMine test] ...":
#   !tm put    - your nearest AT mine (within 5 m of you) is moved to TEST_SPOT: the rail crossing by Train Accident,
#                6 cm under its deck, where captain-cuddles' mine stuck (=FL= 08.11 21:03); texmine then handles it
#                as any mine (lifts, under the map, the countdown); at the next look the chat says where it is
#   !tm stuck  - your nearest AT mine (within 5 m) is handled as one the game will not move: the countdown, then 0
#                health where it lies (it is not moved) - to see whether it goes off, who it hurts, whose kill it is
#   !tm        - the list
# (mm_texmine.CLAYMORES, KILL_PLACER, BLOW_UP, SAFE_RADIUS, VEHICLE_RADIUS lines left from older versions can be
#  removed: they do nothing now; MODE 1 works as MODE 2)
#
# The log: "loaded", "round on" (faces watched), one line for each mine found (where, in what, how long after it was
# laid, who laid it, what was done), "lifted - now at" / "lies still ... after lift n: not in an object" /
# "... again after 3 lifts - taken away", and at the end of every round a summary: who had how many mines in objects.
#
# History
# 2.1.1 (2026-11-09) Sagara: "can you add a text command that lays the mine where needed, for a test?" - TEST_CMDS 1:
#   '!tm put' (your nearest mine to TEST_SPOT, 6 cm under the crossing's deck), '!tm stuck' (your nearest mine
#   straight to the countdown and 0 health, not moved), '!tm' (the list); TEST_ADMINS: who may (names; '' - anybody).
#   A script cannot make a mine out of nothing: lay one first. Off by default; nothing else changed.
# 2.1.0 (2026-11-09) Sagara: "set the mine off whoever is near if it could not be moved, and say in the chat 'the mine
#   goes off in 3, 2, 1' - and set it off". A mine the game will not move (=FL= 08.11 21:03: captain-cuddles' mine at
#   the rail crossing - 3 lifts in 0.35 s did not take, the game would not take it under the map, it lay under the deck
#   58 s with him 1.4-3 m away, until he took it with the wrench): STUCK_BLAST 1 - BLAST_COUNT 3 chat lines a second
#   apart (MSG_COUNT with the owner's name / MSG_COUNT_NOBODY, then MSG_TICK 2, 1), then 0 health where it lies,
#   whoever is near; again every second while the game still has it; after BLAST_TRIES 5 MSG_FAILED once. The log
#   names who was within 10 m at the countdown and at the blast; the round summary counts the countdowns and how the
#   mines went. Unchanged: the 3 lifts, the 5 tries under the map first, CUT_COLLISION only with nobody within 8 m.
#   Not known yet: whether 0 health sets such a mine off at all (02.11: a fresh one fell through the ground; 06.11:
#   ten did nothing) - and whose kill a blast is.
# 2.0.0 (2026-11-08) On the bus mm_flbus (Sagara: "the scripts do not work without the bus; everything shared in it"):
#   the timer, the rounds and the reading of the AT mines are the bus's (TYPE_EVERY is mm_flbus.TYPE_EVERY); the rule,
#   what is done with a mine, the messages and the log lines are 1.6.0's.
# 1.6.0 (2026-11-07) Sagara: no killing of the player for a mine laid in an object; the "level with the surface" rule
#   at 2 cm. Gone: mode 1 (the placer killed / the mine blown up where it lies; MODE 1 now works as MODE 2),
#   KILL_PLACER, BLOW_UP, SAFE_RADIUS, MSG_KILLED. A mine the game will not move is set off where it lies only when
#   nobody at all - its owner too, crews of vehicles too - is within WAIT_RADIUS 10 m (1.5.1 did it with its owner
#   there, and at once when a vehicle came within 25 m: VEHICLE_RADIUS gone); CUT_COLLISION's 0 health likewise only
#   with nobody within 8 m. FLUSH 0.02: an upward face of a watched object up to 2 cm under the mine's top covers the
#   point too (FLUSH_ONLY: only those objects, comma-separated; '' all). In the 140 =FL= Karkand rounds: +5 mines
#   hidden where they came to rest - 3 at the ends of the rail crossing's ramps, 2 in the storage building west of
#   the Warehouse flag (lrgstrgopen02); 1 cm would have given the 2 at the crossing only.
# 1.5.1 (2026-11-07) less asked of the game (a busy 64-player round, counted: ~2,300 calls a second -> ~120): the
#   game is asked for the AT mines by their template (getObjectsOfTemplate), not for every projectile with its name
#   (the bullets too); every TYPE_EVERY 5 s every projectile is still looked at - that finds a mine of a new name, and
#   if the template's list ever lacks a mine the other has, it goes back to every projectile for good. A mine that has
#   lain still STILL_SLOW 5 s is looked at every SLOW_EVERY 1 s (none of the 5,082 mines of the 140 =FL= rounds moved
#   again after lying still 5 s; a mine on 0,0,0 - about to be laid again - is looked at every 0.1 s as before). At
#   the end of each round the log says how long a look took.
# 1.5.0 (2026-11-07) the production version: MODE 3 with LIFT_ASIDE 0 (tested by Sagara 07.11: works); TEST_CHAT 0;
#   claymores taken out of the script (a script of their own later); a mine found only by the fall rule is put back
#   or taken away without a chat message and is not counted for the kick (in 140 =FL= rounds the fall rule would
#   have caught 15 legit mines lying on a soldier or an empty vehicle); a summary of each round in the log.
# 1.4.2 (2026-11-07) MODE 3 (Sagara's idea): lift the mine 1 m instead of taking it under the map - the game puts
#   back a mine moved DOWN (all 24 of the 06.11 test "cannot be moved") but lets it move UP. LIFT_ASIDE 1: to the
#   nearest open ground up to 6 m away (found for 298 of 315 hidden mines of the 140 rounds; 295 would land visible).
# 1.4.1 (2026-11-07) CUT_COLLISION (setDamage(0) first in mode 2: a fresh mine loses its collision and falls through
#   the ground - 02.11 test); a soldier's setDamage for a mine without its own (14 of 24 on 06.11); KICK_AFTER 0 and
#   FALL_RULE 1 by default (Sagara).
# 1.4.0 (2026-11-07) from all 140 =FL= Karkand rounds of bf2replaydecode.duckdns.org (11.10-06.11, 5,082 AT mines,
#   each one's path from its demo replayed through this code): PASS_RULE (went down through a watched face);
#   wpipe_construct and lrg_stonebridge added; ModManager 1.0 is enough (1.3.1 asked for 1.6, so a ModManager 1.4
#   server did not load it: from 03.11 to 06.11, 38 mines lay hidden on =FL= for 23-577 s, 13 went off). Of the 315
#   mines hidden at the end 312 caught (the 3 left lie at an object's edge), none of the 4,677 never in an object.
# 1.3.1 (2026-11-03) texmine.py's production version, made one ModManager module (settings from modmanager.con).

__version__ = 2.11

__required_modules__ = {
	'modmanager': 1.0,
	'mm_flbus': 1.01
}

__supports_reload__ = False

__supported_games__ = {
	'bf2': True,
	'bf2142': False,
	'bfheroes': False,
	'bfp4f': False
}

__description__ = 'TexMine v2.1.1 (ModManager module, on mm_flbus)'

import bf2
import host
import sys
import mm_flbus as BUS

VERSION = '2.1.1'

# ------------------------------------------------------------------ settings
MODE = 3               # what happens to a mine laid inside an object (nobody is killed in either):
                       #   3 - it is lifted LIFT_UP m out of the object and falls back on the ground by itself (it stays
                       #       the player's mine); in an object again LIFT_TRIES times: as mode 2
                       #   2 - it just disappears the moment it is laid (under the map; no blast where it lay)
CHECK_EVERY = 0.1      # s: how often the mines are looked at (each one is checked again whenever it moves)
STILL_SLOW = 5.0       # s: a mine that has lain still this long ...
SLOW_EVERY = 1.0       # s: ... is looked at only this often (0: every look, as before 1.5.1)
PLACER_RADIUS = 1.0    # m: who laid it = the nearest living soldier on foot this close to it when it appears
                       #    (an engineer, when one is there)
REMOVE_DEPTH = 1000.0  # m: a mine taken away goes this far under the map and is set off there (nobody hears it)
CUT_COLLISION = 1      # 1: first set the mine to 0 health where it lies - a fresh mine does not go off then but falls
                       #    through the ground (02.11 test); only when nobody at all is within 8 m
WAIT_RADIUS = 10.0     # m: with STUCK_BLAST 0, a mine the game will not move is set off where it lies only when
                       #    nobody at all (its owner too, a vehicle's crew too) is this close
STUCK_BLAST = 1        # 1 (2.1.0): a mine the game will not move (after the lifts and 5 tries to take it under the
                       #    map) is set off where it lies after a countdown in the chat - WHOEVER is near: it can kill
                       #    them; 0: as 2.0.0 - only when nobody at all is within WAIT_RADIUS
BLAST_COUNT = 3        # s: the countdown - a chat line every second (3, 2, 1), then 0 health
BLAST_TRIES = 5        # 0 health again every second while the game still has the mine; after this many MSG_FAILED is
                       #    said once (it is still tried every second, for up to 600 s after it was found)
FALL_RULE = 1          # 1: also a mine that lay still on ANY object (one not in the data too) and then dropped straight
                       #    down 0.15-1.5 m. Note: on =FL= Karkand it would have taken 15 legit mines in 140 rounds
                       #    (lying on a soldier or on an empty vehicle) for 1 hidden one the other rules miss
KICK_AFTER = 0         # both modes: kick a player after this many such mines in one round (0: never - the default)
SAY = 1                # 1: tell everybody in the chat
MSG_REMOVED = '[TexMine] %s laid a mine inside an object: the mine is removed.'
MSG_NOBODY = '[TexMine] A mine laid inside an object has been removed.'
MSG_LIFTED = '[TexMine] %s laid a mine inside an object: the mine is put back on the ground.'
MSG_COUNT = '[TexMine] The mine of %s is stuck in an object and cannot be moved: it goes off in %d...'
MSG_COUNT_NOBODY = '[TexMine] A mine stuck in an object cannot be moved: it goes off in %d...'
MSG_TICK = '[TexMine] %d...'
MSG_FAILED = '[TexMine] The stuck mine did not go off. An engineer can remove it with the wrench.'
LIFT_UP = 1.0          # mode 3: m over where it lay
LIFT_ASIDE = 0         # mode 3: 1 - and out to the nearest open ground (no watched object there), up to 6 m away;
                       #    0 - straight up (it falls back onto the same object)
LIFT_TRIES = 3         # mode 3: lifted at most this many times; in an object again after that: as mode 2
MSG_KICK = '[TexMine] %s is kicked: %d mines laid inside objects this round.'
TEST_CHAT = 0          # 1: say in the chat what was found for EVERY mine (for a test: lay mines and read the chat)
TEST_CMDS = 0          # 1: the test chat commands '!tm put', '!tm stuck', '!tm' (see the top of the file) - for a test
                       #    server only
TEST_ADMINS = ''       # who may use them: names, comma-separated, as in the game ('' - anybody, when TEST_CMDS is 1)
TEST_SPOT = '-113.22 150.33 266.17'    # '!tm put': x height z - Karkand's rail crossing by Train Accident, 6 cm under
                       #    its deck (captain-cuddles' mine, =FL= 08.11 21:03, 8:05 into the round)
TEST_NEAR = 5.0        # m: the commands take the AT mine nearest to the player within this
LOG_FILE = 'texmine.log'   # in the server folder; '' - no log

# the rule (the site's mineHidden, v266)
MINE_TOP = 0.05        # m: the mine's top over its position
MINE_R = 0.13          # m: the 8 points round the middle
COVER = 0.5            # m: a face this far over a point covers it
UNDER = 0.7            # m: under the object's top - the top this far over the point at most
DEEP = 4.0             # m: inside a closed solid (a bottom under the point) - its top this far over it at most
EDGE = 0.01            # m: a face closer than this over a point does not count (a mine lying right at an edge)
FLUSH = 0.02           # m: an upward face of a watched object up to this far UNDER the mine's top covers the point too
                       #    (the mine sunk into it, its top level with the surface); 0: off (the site's rule only)
FLUSH_ONLY = ''        # the objects FLUSH is used for, comma-separated (e.g. 'train_rail_crossing'); '': all
MAX_SEEN = 1           # hidden: at most this many of the 9 points uncovered
REST_MIN = 0.4         # s: the fall rule - still this long (within 0.08 m) before the drop
FALL_MIN = 0.15        # m: the drop at least ...
FALL_MAX = 1.5         # m: ... and at most
FALL_SIDE = 0.25       # m: sideways at most (|dx| + |dz|) from where it lay to where it is
PASS_RULE = 1          # 1: a mine that went down through a face of a watched object (it was over the face at one look
                       #    and under it at the next) - fell into the object, wherever it ended up
PASS_UNDER = 0.03      # m: its top this far under the face at least (a mine sitting on a face dips into it a little)
PASS_OVER = 0.01       # m: ... having been no lower than this under it the look before

# ------------------------------------------------------------------ log
F = None

def log(text):
    if F is not None:
        F.log(text)
    else:
        BUS.write_log(LOG_FILE, text)

def err_text():
    t, v, tb = sys.exc_info()
    line = '?'
    try:
        while tb.tb_next:
            tb = tb.tb_next
        line = str(tb.tb_lineno)
    except:
        pass
    return '%s: %s (line %s)' % (t, v, line)

def say(text):
    BUS.say(text)

def now():
    return BUS.now()

# ------------------------------------------------------------------ the objects' faces on the map now
CELL = 4.0
OFFS = [(0.0, 0.0)]
for _c, _s in [(1.0, 0.0), (0.70710678, 0.70710678), (0.0, 1.0), (-0.70710678, 0.70710678),
               (-1.0, 0.0), (-0.70710678, -0.70710678), (0.0, -1.0), (0.70710678, -0.70710678)]:
    OFFS.append((_c * MINE_R, _s * MINE_R))

_mesh_cache = {}

def mesh(name):
    m = _mesh_cache.get(name)
    if m is None:
        m = [int(v) / 100.0 for v in MESHES[name].split(',')]
        _mesh_cache[name] = m
    return m

def build_faces(mapname):
    # -> {(cell x, cell z): [face, ...]}; face = (x0, z0, y0, e1x, e1z, d1, e2x, e2z, d2, det, xmin, xmax, zmin, zmax,
    #    name, up: the face looks up - the top of the solid under it)
    cells = {}
    n = 0
    for pl in PLACES.get(mapname, []):
        name = pl[0]
        px, py, pz = pl[1], pl[2], pl[3]
        r = [v / 10000.0 for v in pl[4:13]]
        mirror = (r[0] * (r[4] * r[8] - r[5] * r[7]) - r[1] * (r[3] * r[8] - r[5] * r[6]) +
                  r[2] * (r[3] * r[7] - r[4] * r[6])) < 0
        V = mesh(name)
        i = 0
        while i < len(V):
            w = []
            for k in (0, 3, 6):
                x, y, z = V[i + k], V[i + k + 1], V[i + k + 2]
                w.append((r[0] * x + r[1] * y + r[2] * z + px,
                          r[3] * x + r[4] * y + r[5] * z + py,
                          r[6] * x + r[7] * y + r[8] * z + pz))
            i = i + 9
            (x0, y0, z0), (x1, y1, z1), (x2, y2, z2) = w
            e1x, e1z, e2x, e2z = x1 - x0, z1 - z0, x2 - x0, z2 - z0
            det = e1x * e2z - e2x * e1z
            if -1e-6 < det < 1e-6:
                continue
            up = (det > 0) != mirror
            f = (x0, z0, y0, e1x, e1z, y1 - y0, e2x, e2z, y2 - y0, det,
                 min(x0, x1, x2), max(x0, x1, x2), min(z0, z1, z2), max(z0, z1, z2), name, up)
            for cx in range(int(f[10] // CELL), int(f[11] // CELL) + 1):
                for cz in range(int(f[12] // CELL), int(f[13] // CELL) + 1):
                    cells.setdefault((cx, cz), []).append(f)
            n = n + 1
    return cells, n

def cover_at(cells, x, z, top):
    # the object over the point (x, z), or None:
    #  - a face of it between top + EDGE and top + COVER over the point, or
    #  - the point is under the object's top: the nearest face over it looks up (it is the top of the object, seen
    #    from inside or from under it) no higher than top + UNDER - or no higher than top + DEEP when the nearest face
    #    under the point looks down (the object's bottom: the point is inside a closed solid)
    above, ah, below, bh, flush = None, top + DEEP, None, -1e9, None
    for f in cells.get((int(x // CELL), int(z // CELL)), ()):
        if x < f[10] or x > f[11] or z < f[12] or z > f[13]:
            continue
        dx, dz, det = x - f[0], z - f[1], f[9]
        a = (dx * f[7] - f[6] * dz) / det
        if a < 0.0 or a > 1.0:
            continue
        b = (f[3] * dz - dx * f[4]) / det
        if b < 0.0 or a + b > 1.0:
            continue
        h = f[2] + a * f[5] + b * f[8]
        if h >= top:
            if top + EDGE <= h <= top + COVER:
                return f[14]
            if h <= ah:
                above, ah = f, h
        else:
            if h >= top - FLUSH and f[15] and flush is None and flush_for(f[14]):
                flush = f
            if h >= bh:
                below, bh = f, h
    if above is not None and above[15] and ah >= top + EDGE:
        if ah <= top + UNDER or (below is not None and not below[15]):
            return above[14]
    if flush is not None:
        return flush[14]          # (1.6.0: level with its surface)
    return None

def flush_for(name):
    # 1 if FLUSH is used for this object
    only = S.get('flush_only')
    if only is None:
        only = {}
        for n in str(FLUSH_ONLY or '').split(','):
            n = n.strip().lower()
            if n:
                only[n] = 1
        S['flush_only'] = only
    return not only or name.lower() in only

def went_through(cells, prev, pos):
    # the watched object whose face (looking up) the mine went down through between prev and pos: the face over the
    # place it is now, its top no higher than PASS_UNDER under the face, the look before no lower than PASS_OVER under it
    if pos[1] > prev[1] - PASS_UNDER:
        return None
    x, z = pos[0], pos[2]
    lo, hi = pos[1] + MINE_TOP + PASS_UNDER, prev[1] + MINE_TOP + PASS_OVER
    for f in cells.get((int(x // CELL), int(z // CELL)), ()):
        if not f[15] or x < f[10] or x > f[11] or z < f[12] or z > f[13]:
            continue
        dx, dz, det = x - f[0], z - f[1], f[9]
        a = (dx * f[7] - f[6] * dz) / det
        if a < 0.0 or a > 1.0:
            continue
        b = (f[3] * dz - dx * f[4]) / det
        if b < 0.0 or a + b > 1.0:
            continue
        h = f[2] + a * f[5] + b * f[8]
        if lo <= h <= hi:
            return f[14]
    return None

def hidden_in(cells, pos):
    # the object the mine at pos (x, height, z) is hidden in, or None
    x, y, z = pos
    top = y + MINE_TOP
    seen = 0
    what = None
    for ox, oz in OFFS:
        o = cover_at(cells, x + ox, z + oz, top)
        if o is None:
            seen = seen + 1
            if seen > MAX_SEEN:
                return None
        elif what is None:
            what = o
    return what

# ------------------------------------------------------------------ state
S = {'map': None, 'cells': {}, 'on': 0, 'mines': {}, 'count': {}, 'warned': {}, 'nfaces': 0, 'serial': 0, 'tally': {},
     'idle': 0, 'nlooks': 0, 'nmines': 0, 'bl': [0, 0, 0, 0, 0]}

def current_mines(t=None):
    # [(object, kind)]: the AT mines this frame - the bus's (by their template; every projectile every
    # mm_flbus.TYPE_EVERY s for new names)
    if t is None:
        t = now()
    out = []
    for o, k in BUS.objects('atmine', t):
        out.append((o, 'AT mine'))
    return out

def obj_key(o):
    try:
        return o.token
    except:
        return None

def players():
    try:
        return bf2.playerManager.getPlayers()
    except:
        return []

def soldier_pos(p):
    # (x, height, z) of a living soldier on foot, or None
    try:
        if not p.isAlive():
            return None
        s = p.getDefaultVehicle()
        v = p.getVehicle()
        if v is not None and s is not None and v.templateName.lower() != s.templateName.lower():
            return None
        return s.getPosition()
    except:
        return None

def any_pos(p):
    try:
        if not p.isAlive():
            return None
        return p.getVehicle().getPosition()
    except:
        return None

def vehicle_near(pos, r=7.0):
    # a player in a vehicle within r m (a mine that lay on a vehicle drops when it drives off)
    for p in players():
        try:
            if not p.isAlive():
                continue
            v = p.getVehicle()
            sd = p.getDefaultVehicle()
            if v is None or sd is None or v.templateName.lower() == sd.templateName.lower():
                continue
            q = v.getPosition()
        except:
            continue
        if (q[0] - pos[0]) ** 2 + (q[2] - pos[2]) ** 2 <= r * r and abs(q[1] - pos[1]) <= 5.0:
            return 1
    return 0

def kit_name(p):
    try:
        return p.getKit().templateName.lower()
    except:
        return ''

def find_placer(pos, kind):
    best, bd, bestk, bdk = None, PLACER_RADIUS * PLACER_RADIUS, None, PLACER_RADIUS * PLACER_RADIUS
    want = 'engineer'
    for p in players():
        q = soldier_pos(p)
        if q is None:
            continue
        dx, dz, dy = q[0] - pos[0], q[2] - pos[2], q[1] - 1.0 - pos[1]
        if dy > 3.0 or dy < -3.0:
            continue
        d = dx * dx + dz * dz
        if d <= bd:
            best, bd = p, d
        if d <= bdk and kit_name(p).find(want) >= 0:
            bestk, bdk = p, d
    if bestk is not None:
        return bestk
    return best

def player_name(p):
    try:
        return p.getName()
    except:
        return '?'

# ------------------------------------------------------------------ what happens to a hidden mine
BELOW_MAP = -100.0     # m: a mine lower than this has been taken under the map
JUMP = 20.0            # m: a mine that moves this far in one look is used again by the game (a new mine)

def wrappers(o):
    # the mine, and the same mine as the game gives it by its template (one more way to reach it)
    out = [o]
    k = obj_key(o)
    if k is None:
        return out
    try:
        for x in bf2.objectManager.getObjectsOfTemplate(o.templateName):
            if obj_key(x) == k and x is not o:
                out.append(x)
    except:
        pass
    return out

def try_move(o, m):
    # under the map with it; m['moved'] once it is there
    p0 = m['pos0']
    m['move_t'] = now()
    ws = [o]
    if m['tries'] > 0:
        ws = wrappers(o)
    for w in ws:
        try:
            w.setPosition((p0[0], p0[1] - REMOVE_DEPTH, p0[2]))
        except:
            if not m['moveerr']:
                m['moveerr'] = 1
                log('setPosition failed: ' + err_text())
    try:
        q = o.getPosition()
        if q[1] < BELOW_MAP:
            m['moved'] = 1
    except:
        pass

def func_of(bm):
    # the function behind a bound method (a soldier's setDamage), or None
    f = getattr(bm, 'im_func', None)
    if f is None:
        f = getattr(bm, '__func__', None)
    return f

def borrowed_set():
    # the function behind a living soldier's setDamage: called with the mine, it sets the mine's health (it does so
    # for vehicles, which the game also hands out without setDamage of their own)
    for p in players():
        try:
            if not p.isAlive():
                continue
            f = func_of(p.getDefaultVehicle().setDamage)
        except:
            continue
        if f is not None:
            return f
    return None

def set_off(o, m):
    m['off_t'] = now()
    m['offs'] = m['offs'] + 1
    own = getattr(o, 'setDamage', None)
    how = 'its own setDamage'
    try:
        if own is not None:
            own(0.0)
        else:
            f = borrowed_set()
            if f is None:
                if not m['offerr']:
                    m['offerr'] = 1
                    log('mine %s has no setDamage and there is no soldier\'s to use' % m['id'])
                return
            how = "a soldier's setDamage"
            f(o, 0.0)
    except:
        if not m['offerr']:
            m['offerr'] = 1
            log('mine %s: setDamage failed (%s): %s' % (m['id'], how, err_text()))
        return
    if not m['offhow']:
        m['offhow'] = how
        log('mine %s set to 0 health with %s' % (m['id'], how))

def someone_near(pos, r, but=None):
    r2 = r * r
    for p in players():
        if but is not None and p.index == but.index:
            continue
        q = any_pos(p)
        if q is not None and (q[0] - pos[0]) ** 2 + (q[1] - pos[1]) ** 2 + (q[2] - pos[2]) ** 2 <= r2:
            return 1
    return 0

def root_name(o):
    try:
        rp = bf2.objectManager.getRootParent(o)
        if obj_key(rp) == obj_key(o):
            return 'itself'
        return rp.templateName
    except:
        return '?'

def follow_up(o, m, pos, t):
    # a hidden mine after the first step, every look while the game still has it
    if not m['sunk'] and pos[1] < m['pos0'][1] - 1.0:
        m['sunk'] = 1
        log('mine %s fell through the ground (%.1f m under where it lay) %.1f s after it was found' % (m['id'],
            m['pos0'][1] - pos[1], t - m['acted']))
        if m['blast_t'] is not None:
            S['bl'][3] = S['bl'][3] + 1
        if TEST_CHAT:
            say('[TexMine test] mine %s fell through the ground %.1f s after it was found' % (m['id'], t - m['acted']))
    if pos[1] < BELOW_MAP:
        if not m['moved']:
            m['moved'] = 1
            log('mine %s: under the map %.1f s after it was found' % (m['id'], t - m['acted']))
        # set it off there, again every second: a freshly laid mine does not go off at once (02.11 test server)
        if t - m['off_t'] >= 1.0 and t - m['acted'] < 120:
            set_off(o, m)
        return
    if m['tries'] < 5:
        if t - m['move_t'] >= 0.2:
            m['tries'] = m['tries'] + 1
            try_move(o, m)
        return
    # the game does not let this mine move: STUCK_BLAST 1 (2.1.0) - a countdown in the chat, then set off where it
    # lies whoever is near; STUCK_BLAST 0 - set off only when nobody at all (the one who laid it too, a vehicle's crew
    # too) is within WAIT_RADIUS; either way try moving it now and then
    if not m['stuck']:
        m['stuck'] = 1
        m['count_t'] = t
        if STUCK_BLAST:
            S['bl'][0] = S['bl'][0] + 1
            log('mine %s at (%.2f, %.2f, %.2f) cannot be moved (its root: %s) - set off where it lies in %d s, whoever '
                'is near (%s)' % (m['id'], pos[0], pos[1], pos[2], root_name(o), BLAST_COUNT, near_text(pos)))
        else:
            log('mine %s at (%.2f, %.2f, %.2f) cannot be moved (its root: %s) - it is set off where it lies when '
                'nobody is within %.0f m' % (m['id'], pos[0], pos[1], pos[2], root_name(o), WAIT_RADIUS))
        if TEST_CHAT:
            say('[TexMine test] mine %s could not be moved' % m['id'])
    if t - m['acted'] > 600:
        return
    if STUCK_BLAST:
        if not m['sunk']:
            countdown(o, m, pos, t)     # (one falling through the ground is on its way out: set off under the map)
    elif t - m['off_t'] >= 1.0 and not someone_near(pos, WAIT_RADIUS):
        set_off(o, m)
    if t - m['move_t'] >= 2.0 and not m['force']:
        try_move(o, m)

def test_spot():
    # TEST_SPOT as (x, height, z); Karkand's crossing if it cannot be read
    try:
        a = str(TEST_SPOT).replace(',', ' ').split()
        return (float(a[0]), float(a[1]), float(a[2]))
    except:
        return (-113.22, 150.33, 266.17)

def may_test(name):
    if not TEST_ADMINS:
        return 1
    for n in str(TEST_ADMINS).split(','):
        if n.strip() and n.strip().lower() == name.lower():
            return 1
    return 0

def on_chat(playerId, text, channel=None, flags=None):
    # TEST_CMDS 1: '!tm put', '!tm stuck', '!tm' typed in the chat
    if not TEST_CMDS or not S['on']:
        return
    try:
        s = str(text)
    except:
        return
    i = s.lower().find('!tm')
    if i < 0:
        return
    w = s[i:].lower().split()
    if not w or w[0] != '!tm':
        return
    cmd = 'help'
    if len(w) > 1:
        cmd = w[1]
    try:
        p = bf2.playerManager.getPlayerByIndex(int(playerId))
    except:
        p = None
    if p is None:
        return
    name = player_name(p)
    if not may_test(name):
        say('[TexMine test] %s may not use the test commands (mm_texmine.TEST_ADMINS)' % name)
        return
    if cmd not in ('put', 'stuck'):
        say("[TexMine test] lay an AT mine, stand by it and type: '!tm put' - it is moved into the rail crossing by "
            "Train Accident; '!tm stuck' - it goes off after the countdown, not moved")
        return
    q = any_pos(p)
    if q is None:
        say('[TexMine test] %s: only a living player can use it' % name)
        return
    t = now()
    best = None
    for o, kind in current_mines(t):
        try:
            pos = o.getPosition()
        except:
            continue
        if parked_at(pos):
            continue
        d = ((pos[0] - q[0]) ** 2 + (pos[1] - q[1]) ** 2 + (pos[2] - q[2]) ** 2) ** 0.5
        if d <= TEST_NEAR and (best is None or d < best[0]):
            best = (d, o, pos)
    if best is None:
        say('[TexMine test] %s: no AT mine within %.0f m of you' % (name, TEST_NEAR))
        return
    d, o, pos = best
    m = S['mines'].get(obj_key(o))
    if m is None:
        say('[TexMine test] %s: that mine has not been looked at yet - type it again' % name)
        return
    if m['stuck'] or m['count_t'] is not None:
        say('[TexMine test] mine %s is already being set off' % m['id'])
        return
    if cmd == 'put':
        if m['acted'] is not None:
            say('[TexMine test] mine %s is already being taken away - lay another one' % m['id'])
            return
        to = test_spot()
        try:
            o.setPosition(to)
        except:
            log('test: setPosition failed: ' + err_text())
            say('[TexMine test] the mine could not be moved (setPosition failed)')
            return
        # judged again where it comes to lie: 'last' 5 cm off, so that the next look counts it as moved (and not as a
        # jump of a mine the game uses again)
        m['last'] = (to[0], to[1] + 0.05, to[2])
        m['still'], m['rest'], m['lastrest'], m['seen_t'] = t, None, None, t
        m['lifts'], m['lift_chk'], m['put_t'], m['put_said'] = 0, 0, t, 0
        log('test: %s - "!tm put": mine %s moved from (%.2f, %.2f, %.2f) to the test spot (%.2f, %.2f, %.2f)' % (name,
            m['id'], pos[0], pos[1], pos[2], to[0], to[1], to[2]))
        say('[TexMine test] mine %s moved %.0f m to the rail crossing test spot' % (m['id'],
            ((pos[0] - to[0]) ** 2 + (pos[1] - to[1]) ** 2 + (pos[2] - to[2]) ** 2) ** 0.5))
        return
    # 'stuck': straight to the countdown where it lies, not moved
    m['acted'], m['stage'], m['pos0'] = t, 'away', pos
    m['tries'], m['move_t'], m['force'] = 5, t, 1
    log('test: %s - "!tm stuck": mine %s at (%.2f, %.2f, %.2f) handled as one the game will not move (not moved; %s)'
        % (name, m['id'], pos[0], pos[1], pos[2], near_text(pos)))
    say('[TexMine test] mine %s: handled as stuck - the countdown starts' % m['id'])

def near_text(pos, r=10.0):
    # who is within r m of pos (for the log): 'within 10 m: A 1.4 m, B 2.8 m' or 'nobody within 10 m'
    L = []
    for p in players():
        q = any_pos(p)
        if q is None:
            continue
        d = ((q[0] - pos[0]) ** 2 + (q[1] - pos[1]) ** 2 + (q[2] - pos[2]) ** 2) ** 0.5
        if d <= r:
            L.append((d, player_name(p)))
    if not L:
        return 'nobody within %.0f m' % r
    L.sort()
    return 'within %.0f m: %s' % (r, ', '.join(['%s %.1f m' % (n, d) for d, n in L]))

def countdown(o, m, pos, t):
    # 2.1.0: BLAST_COUNT chat lines a second apart (3, 2, 1), then 0 health where the mine lies whoever is near; again
    # every second while the game still has it; MSG_FAILED once after BLAST_TRIES
    while m['said_n'] < BLAST_COUNT and t - m['count_t'] >= m['said_n'] - 0.001:
        n = BLAST_COUNT - m['said_n']
        m['said_n'] = m['said_n'] + 1
        if not SAY:
            continue
        if m['said_n'] > 1:
            say(MSG_TICK % n)
        elif m['placer'] is None:
            say(MSG_COUNT_NOBODY % n)
        else:
            say(MSG_COUNT % (player_name(m['placer']), n))
    if t - m['count_t'] < BLAST_COUNT - 0.001 or t - m['off_t'] < 1.0:
        return
    if m['blast_t'] is None:
        m['blast_t'] = t
        S['bl'][1] = S['bl'][1] + 1
        log('mine %s: the countdown is over - set to 0 health where it lies (%s)' % (m['id'], near_text(pos)))
    m['bl_n'] = m['bl_n'] + 1
    set_off(o, m)
    if m['bl_n'] == BLAST_TRIES and not m['failsaid']:
        m['failsaid'] = 1
        S['bl'][4] = S['bl'][4] + 1
        log('mine %s: still there after %d times 0 health (at %.2f, %.2f, %.2f) - it did not go off; tried every second '
            'on' % (m['id'], BLAST_TRIES, pos[0], pos[1], pos[2]))
        if SAY and MSG_FAILED:
            say(MSG_FAILED)

DIRS16 = [(1.0, 0.0), (0.92388, 0.38268), (0.70711, 0.70711), (0.38268, 0.92388), (0.0, 1.0), (-0.38268, 0.92388),
          (-0.70711, 0.70711), (-0.92388, 0.38268), (-1.0, 0.0), (-0.92388, -0.38268), (-0.70711, -0.70711),
          (-0.38268, -0.92388), (0.0, -1.0), (0.38268, -0.92388), (0.70711, -0.70711), (0.92388, -0.38268)]

def face_between(cells, x, z, lo, hi):
    # a face of a watched object over (x, z) between the heights lo and hi
    for f in cells.get((int(x // CELL), int(z // CELL)), ()):
        if x < f[10] or x > f[11] or z < f[12] or z > f[13]:
            continue
        dx, dz, det = x - f[0], z - f[1], f[9]
        a = (dx * f[7] - f[6] * dz) / det
        if a < 0.0 or a > 1.0:
            continue
        b = (f[3] * dz - dx * f[4]) / det
        if b < 0.0 or a + b > 1.0:
            continue
        h = f[2] + a * f[5] + b * f[8]
        if lo <= h <= hi:
            return 1
    return 0

def open_ground(cells, pos):
    # the nearest place (0.6 m steps out to 6 m, 16 ways) where no face of a watched object is from 1 m under the mine
    # to 6 m over it, there and 0.4 m round it: (x, z), or None
    lo, hi = pos[1] - 1.0, pos[1] + 6.0
    r = 0.6
    while r <= 6.01:
        for c, sn in DIRS16:
            x, z = pos[0] + r * c, pos[2] + r * sn
            ok = 1
            for ox, oz in [(0.0, 0.0)] + [(0.4 * c2, 0.4 * s2) for c2, s2 in DIRS16[::2]]:
                if face_between(cells, x + ox, z + oz, lo, hi):
                    ok = 0
                    break
            if ok:
                return (x, z)
        r = r + 0.6
    return None

def tally(m, name):
    # the round's count: name -> [mines found in objects, of them by the fall rule only, taken away after 3 lifts]
    if m['tallied']:
        return
    m['tallied'] = 1
    c = S['tally'].get(name)
    if c is None:
        c = [0, 0, 0]
        S['tally'][name] = c
    c[0] = c[0] + 1
    if m['byfall']:
        c[1] = c[1] + 1

def round_end(t):
    if S['idle']:
        return
    L = []
    n = 0
    for name in S['tally'].keys():
        c = S['tally'][name]
        n = n + c[0]
        L.append((-c[0], name, c))
    L.sort()
    parts = []
    for k, name, c in L:
        x = []
        if c[1]:
            x.append('%d by the fall rule only' % c[1])
        if c[2]:
            x.append('%d taken away after %d lifts' % (c[2], LIFT_TRIES))
        if x:
            parts.append('%s %d (%s)' % (name, c[0], ', '.join(x)))
        else:
            parts.append('%s %d' % (name, c[0]))
    if n:
        log('round summary on %s: %d mines found in objects - %s' % (S['map'], n, '; '.join(parts)))
    else:
        log('round summary on %s: no mines found in objects' % S['map'])
    S['tally'] = {}
    b = S['bl']
    if b[0]:
        log('stuck mines this round (could not be moved): %d - countdowns over %d, then gone from the game %d, fell '
            'through the ground %d, still there after %d times 0 health %d' % (b[0], b[1], b[2], b[3], BLAST_TRIES, b[4]))
    S['bl'] = [0, 0, 0, 0, 0]
    if S['nlooks']:
        log('mines a look on average this round: %.0f (asked of the bus: by their template, every projectile every %.0f '
            's)' % (float(S['nmines']) / S['nlooks'], BUS.TYPE_EVERY))
    if F is not None:
        log(F.load_line(t))

def put_back(o, m, pos, what):
    # mode 3: the mine is lifted out of the object (and out to open ground with LIFT_ASIDE) and falls by itself; it is
    # watched as before and judged again where it comes to lie
    placer = m['placer']
    name = '(nobody near)'
    if placer is not None:
        name = player_name(placer)
    m['lifts'] = m['lifts'] + 1
    if m['lifts'] > LIFT_TRIES:
        log('mine %s in %s again after %d lifts at (%.2f, %.2f, %.2f) - taken away as in mode 2' % (m['id'], what,
            LIFT_TRIES, pos[0], pos[1], pos[2]))
        t3 = S['tally'].get(name)
        if t3 is not None:
            t3[2] = t3[2] + 1
        if TEST_CHAT:
            say('[TexMine test] mine %s went into an object again after %d lifts - taken away' % (m['id'], LIFT_TRIES))
        m['acted'] = now()
        m['pos0'] = pos
        m['stage'] = 'away'
        if CUT_COLLISION and not someone_near(pos, 8.0):
            set_off(o, m)
        try_move(o, m)
        return
    spot = None
    if LIFT_ASIDE:
        spot = open_ground(S['cells'], pos)
    x, z, how = pos[0], pos[2], 'straight up'
    if spot is not None:
        x, z = spot
        how = '%.1f m aside to open ground' % ((abs(x - pos[0]) ** 2 + abs(z - pos[2]) ** 2) ** 0.5)
    elif LIFT_ASIDE:
        how = 'straight up (no open ground within 6 m)'
    to = (x, pos[1] + LIFT_UP, z)
    try:
        o.setPosition(to)
    except:
        log('setPosition failed: ' + err_text())
    t = now()
    m['lift_t'], m['lift_to'], m['lift_chk'], m['restlog'] = t, to, 1, 0
    m['rest'], m['lastrest'], m['still'], m['last'] = None, None, t, to
    log('%s mode 3: %s %s in %s at (%.2f, %.2f, %.2f) [%.2f s after it appeared], laid by %s%s - lifted %.1f m, %s '
        '(lift %d)%s' % (S['map'], m['kind'], m['id'], what, pos[0], pos[1], pos[2], t - m['t0'], name,
        (placer is not None and ' (%s)' % kit_name(placer)) or '', LIFT_UP, how, m['lifts'],
        (m['byfall'] and ' - the fall rule only: nothing said in the chat, not counted for a kick') or ''))
    if TEST_CHAT:
        say('[TexMine test] %s %s HIDDEN in %s - lifted %.1f m, %s (lift %d)' % (m['kind'], m['id'], what, LIFT_UP, how,
            m['lifts']))
    tally(m, name)
    if m['byfall'] or m['told']:
        return
    m['told'] = 1
    if SAY:
        if placer is None:
            say(MSG_NOBODY)
        else:
            say(MSG_LIFTED % name)
    if placer is not None and KICK_AFTER > 0:
        c = S['count'].get(name, 0) + 1
        S['count'][name] = c
        if c >= KICK_AFTER:
            if SAY:
                say(MSG_KICK % (name, c))
            log('kick %s (%d)' % (name, c))
            try:
                host.rcon_invoke('admin.kickPlayer %d' % placer.index)
            except:
                log('kick failed: ' + err_text())

def punish(o, m, pos, what):
    if MODE == 3:
        put_back(o, m, pos, what)
        return
    # mode 2 (and a MODE 1 left in modmanager.con: mode 1, the player killed, is gone since 1.6.0): the mine is taken
    # away under the map at once; nobody is killed
    placer = m['placer']
    name = '(nobody near)'
    if placer is not None:
        name = player_name(placer)
    m['acted'] = now()
    m['pos0'] = pos
    m['stage'] = 'away'
    if CUT_COLLISION and not someone_near(pos, 8.0):
        set_off(o, m)
    try_move(o, m)
    how = 'mine taken under the map'
    if not m['moved']:
        how = 'mine to be taken under the map (it did not move at once)'
    log('%s mode 2: %s %s in %s at (%.2f, %.2f, %.2f) [%.2f s after it appeared], laid by %s%s - %s, nobody killed' % (
        S['map'], m['kind'], m['id'], what, pos[0], pos[1], pos[2], now() - m['t0'], name,
        (placer is not None and ' (%s)' % kit_name(placer)) or '', how))
    tally(m, name)
    if m['byfall']:
        log('mine %s: found by the fall rule only - nothing said in the chat, not counted for a kick' % m['id'])
        return
    if SAY:
        if placer is None:
            say(MSG_NOBODY)
        else:
            say(MSG_REMOVED % name)
    if placer is not None and KICK_AFTER > 0:
        c = S['count'].get(name, 0) + 1   # (by name: he is still counted after he joins again)
        S['count'][name] = c
        if c >= KICK_AFTER:
            if SAY:
                say(MSG_KICK % (name, c))
            log('kick %s (%d)' % (name, c))
            try:
                host.rcon_invoke('admin.kickPlayer %d' % placer.index)
            except:
                log('kick failed: ' + err_text())

# ------------------------------------------------------------------ the look every CHECK_EVERY s
def parked_at(p):
    return abs(p[0]) + abs(p[1]) + abs(p[2]) < 0.01

def apart(p, q):
    return abs(p[0] - q[0]) + abs(p[1] - q[1]) + abs(p[2] - q[2])

def new_mine(t, kind, pos):
    S['serial'] = S['serial'] + 1
    m = {'t0': t, 'kind': kind, 'last': pos, 'still': t, 'said': 0, 'acted': None, 'stage': None, 'id': '#%d' % S['serial'],
         'pos0': pos, 'tries': 0, 'parked': 0, 'placer': None, 'moved': 0, 'stuck': 0, 'move_t': -99.0, 'off_t': -99.0,
         'offs': 0, 'moveerr': 0, 'offerr': 0, 'rest': None, 'lastrest': None, 'offhow': None, 'sunk': 0,
         'lifts': 0, 'lift_t': None, 'lift_to': None, 'lift_chk': 0, 'restlog': 0, 'byfall': 0, 'told': 0, 'tallied': 0,
         'seen_t': t, 'count_t': None, 'said_n': 0, 'blast_t': None, 'bl_n': 0, 'failsaid': 0, 'force': 0,
         'put_t': None, 'put_said': 0}
    if parked_at(pos):
        m['parked'] = 1
    else:
        m['placer'] = find_placer(pos, kind)
    return m

def look(t):
    if S['idle']:
        return
    n = look_mines(t)
    S['nlooks'] = S['nlooks'] + 1
    S['nmines'] = S['nmines'] + n

def look_mines(t):
    cells = S['cells']
    seen = {}
    mines = current_mines(t)
    for o, kind in mines:
        k = obj_key(o)
        if SLOW_EVERY > 0 and k is not None:
            m = S['mines'].get(k)
            if m is not None and m['acted'] is None and not m['parked'] and not m['lift_chk'] and \
               t - m['still'] >= STILL_SLOW and t - m['seen_t'] < SLOW_EVERY - 0.001:
                seen[k] = 1               # (lain still long: looked at every SLOW_EVERY s)
                continue
        try:
            pos = o.getPosition()
        except:
            continue
        if k is None:
            # (no token: the same mine = the one seen last time within 0.6 m)
            for kk in S['mines'].keys():
                if kk not in seen and apart(S['mines'][kk]['last'], pos) < 0.6:
                    k = kk
                    break
            if k is None:
                S['serial'] = S['serial'] + 1
                k = 'n%d' % S['serial']
        seen[k] = 1
        parked = parked_at(pos)
        m = S['mines'].get(k)
        if m is None:
            m = new_mine(t, kind, pos)
            S['mines'][k] = m
        elif not parked and (m['parked'] or (m['acted'] is None and apart(m['last'], pos) > JUMP) or
                             (m['acted'] is not None and m['last'][1] < BELOW_MAP and pos[1] > BELOW_MAP)):
            # the game uses the mine again (from 0,0,0, from under the map, or from far away): a new mine of the
            # player who lays it now
            m = new_mine(t, kind, pos)
            S['mines'][k] = m
        m['seen_t'] = t
        if m['put_t'] is not None and not m['put_said'] and t > m['put_t']:
            m['put_said'] = 1
            sp = test_spot()
            d = ((pos[0] - sp[0]) ** 2 + (pos[1] - sp[1]) ** 2 + (pos[2] - sp[2]) ** 2) ** 0.5
            log('test: mine %s %.2f s after the move: at (%.2f, %.2f, %.2f), %.2f m from the test spot' % (m['id'],
                t - m['put_t'], pos[0], pos[1], pos[2], d))
            say('[TexMine test] mine %s after the move: at %.2f %.2f %.2f (%.2f m from the spot)' % (m['id'],
                pos[0], pos[2], pos[1], d))
        if parked:
            if m['acted'] is not None and not m['parked']:
                log('mine %s: taken away by the game (to 0,0,0) %.1f s after it was found' % (m['id'], t - m['acted']))
                if TEST_CHAT:
                    say('[TexMine test] mine %s is gone (%.1f s after it was found)' % (m['id'], t - m['acted']))
            m['parked'] = 1
            m['last'] = pos
            continue
        if m['acted'] is not None:
            follow_up(o, m, pos, t)
            m['last'] = pos
            continue
        if pos[1] < BELOW_MAP:
            m['last'] = pos
            continue
        if m['lift_chk'] and t - m['lift_t'] >= CHECK_EVERY * 0.9:
            m['lift_chk'] = 0
            lt = m['lift_to']
            if abs(pos[0] - lt[0]) + abs(pos[2] - lt[2]) < 0.5 and pos[1] > lt[1] - 0.6:
                log('mine %s: lifted - now at (%.2f, %.2f, %.2f)' % (m['id'], pos[0], pos[1], pos[2]))
            else:
                log('mine %s: did NOT move up - at (%.2f, %.2f, %.2f) (the game put it back?)' % (m['id'], pos[0], pos[1], pos[2]))
                if TEST_CHAT:
                    say('[TexMine test] mine %s did not move up' % m['id'])
        prev = m['last']
        moved = t == m['t0'] or apart(prev, pos) > 0.01
        m['last'] = pos
        # (the fall rule: where it has lain still - within 0.08 m up and down, 0.1 m sideways of where it started to -
        #  and the last such rest that lasted REST_MIN, left at most 1 s ago)
        r = m['rest']
        if r is None or abs(pos[1] - r[0]) > 0.08 or abs(pos[0] - r[1]) + abs(pos[2] - r[2]) > 0.1:
            if r is not None and r[4] - r[3] >= REST_MIN:
                m['lastrest'] = (r[0], r[1], r[2], t)
            m['rest'] = [pos[1], pos[0], pos[2], t, t]
        else:
            r[4] = t
        if moved:
            m['still'] = t
            what = hidden_in(cells, pos)
            if what is not None:
                m['byfall'] = 0
            if what is None and PASS_RULE and t != m['t0']:
                o2 = went_through(cells, prev, pos)
                if o2 is not None:
                    what = '%s (it went down through it)' % o2
                    m['byfall'] = 0
            lr = m['lastrest']
            if what is None and FALL_RULE and lr is not None and t - lr[3] <= 1.0:
                drop = lr[0] - pos[1]
                if FALL_MIN <= drop <= FALL_MAX and abs(pos[0] - lr[1]) + abs(pos[2] - lr[2]) <= FALL_SIDE:
                    if vehicle_near(pos):
                        m['lastrest'] = None
                        log('mine %s dropped %.2f m with a vehicle near - left alone' % (m['id'], drop))
                    else:
                        what = 'something it fell through (it lay %.2f m higher)' % drop
                        m['byfall'] = 1
            if what is not None:
                punish(o, m, pos, what)
                if TEST_CHAT:
                    say('[TexMine test] %s %s at %.1f %.1f %.1f: HIDDEN in %s' % (m['kind'], m['id'], pos[0], pos[2], pos[1], what))
        elif m['lifts'] and not m['restlog'] and t - m['still'] > 1.5:
            m['restlog'] = 1
            log('mine %s lies still at (%.2f, %.2f, %.2f) after lift %d: not in an object' % (m['id'], pos[0], pos[1],
                pos[2], m['lifts']))
            if TEST_CHAT:
                say('[TexMine test] mine %s lies on the ground after lift %d: visible' % (m['id'], m['lifts']))
        elif TEST_CHAT and not m['said'] and t - m['still'] > 0.6:
            m['said'] = 1
            who = '(nobody near)'
            if m['placer'] is not None:
                who = player_name(m['placer'])
            say('[TexMine test] %s of %s at %.1f %.1f %.1f: visible (still watched)' % (m['kind'], who, pos[0], pos[2], pos[1]))
    for k in list(S['mines'].keys()):
        if k not in seen:
            m = S['mines'][k]
            if m['acted'] is not None and not m['parked']:
                log('mine %s: gone from the game %.1f s after it was found (set off %d times)' % (m['id'], t - m['acted'], m['offs']))
                if m['blast_t'] is not None and not m['sunk']:
                    S['bl'][2] = S['bl'][2] + 1
                    log('mine %s: gone %.1f s after the countdown ended (went off?)' % (m['id'], t - m['blast_t']))
                elif m['count_t'] is not None and m['blast_t'] is None:
                    log('mine %s: gone during the countdown (%.1f s into it) - not set off' % (m['id'], t - m['count_t']))
                if TEST_CHAT:
                    say('[TexMine test] mine %s is gone (%.1f s after it was found)' % (m['id'], t - m['acted']))
            del S['mines'][k]
    return len(mines)

# ------------------------------------------------------------------ rounds
def round_start(t):
    S['tally'] = {}
    mp = BUS.S['map'] or ''
    S['map'] = mp
    S['mines'] = {}
    S['count'] = {}
    S['idle'] = 0
    S['nlooks'], S['nmines'] = 0, 0
    S['bl'] = [0, 0, 0, 0, 0]
    if mp in PLACES:
        S['cells'], S['nfaces'] = build_faces(mp)
        what = '%d faces of %d objects watched' % (S['nfaces'], len(PLACES[mp]))
    else:
        S['cells'], S['nfaces'] = {}, 0
        what = 'no objects of this map in the script'
        if not FALL_RULE:
            S['idle'] = 1
            log('round on %s: %s and FALL_RULE 0 - idle' % (mp, what))
            return
        what = what + ' - the fall rule only'
    S['flush_only'] = None
    log('round on %s (mode %d): %s' % (mp, (MODE == 3 and 3) or 2, what))

def texmine_init():
    global F
    if S['on']:
        return
    S['on'] = 1
    F = BUS.feature('texmine', 'Mine', LOG_FILE, 'TexMine')
    F.log_file = LOG_FILE
    F.maps = 'all'
    F.every = CHECK_EVERY
    F.look = look
    F.round_start = round_start
    F.round_end = round_end
    F.test_chat = TEST_CHAT
    if MODE == 3:
        how = 'mines inside objects are lifted %.1f m%s and fall back' % (LIFT_UP, (LIFT_ASIDE and ' out to open ground') or '')
    else:
        how = 'mines inside objects disappear'
        if MODE != 2:
            how = how + ' (mode %s: there is no mode 1 since 1.6.0 - mode 2 used)' % MODE
    if STUCK_BLAST:
        how = how + '; one the game will not move is set off where it lies after a %d s countdown in the chat, ' \
            'whoever is near' % BLAST_COUNT
    else:
        how = how + ', nobody killed'
    if FLUSH > 0:
        how = how + '; a mine level with a surface (to %.0f cm under it%s) counts as in it' % (FLUSH * 100,
            (FLUSH_ONLY and ', on %s only' % FLUSH_ONLY) or '')
    kick = 'no kick'
    if KICK_AFTER > 0:
        kick = 'kick after %d' % KICK_AFTER
    test = ''
    if TEST_CHAT:
        test = '; TEST_CHAT is on'
    if TEST_CMDS:
        BUS.on_event('ChatMessage', on_chat)
        test = test + "; test commands on ('!tm put', '!tm stuck'; for %s; the spot %s)" % (
            (TEST_ADMINS and TEST_ADMINS) or 'anybody', TEST_SPOT)
    log('texmine %s loaded, on mm_flbus %s (mode %d: %s; %s; %d maps with objects; through-rule %s; the fall rule on %s '
        'maps%s)' % (VERSION, BUS.VERSION, MODE, how, kick, len(PLACES), (PASS_RULE and 'on') or 'off',
        (FALL_RULE and 'all') or 'no', test))
    BUS.add(F)

