# ------------------------------------------------------------------ ModManager interface
# The defaults are the values of the settings above. modmanager.con can override them: mm_texmine.<NAME> <value>
configDefaults = {}
for _k in ['MODE', 'CHECK_EVERY', 'PLACER_RADIUS', 'REMOVE_DEPTH',
           'WAIT_RADIUS', 'FALL_RULE', 'PASS_RULE', 'CUT_COLLISION', 'KICK_AFTER', 'SAY',
           'TEST_CHAT', 'LOG_FILE', 'LIFT_UP', 'LIFT_ASIDE', 'LIFT_TRIES', 'STILL_SLOW', 'SLOW_EVERY',
           'FLUSH', 'FLUSH_ONLY', 'STUCK_BLAST', 'BLAST_COUNT', 'BLAST_TRIES', 'MSG_COUNT', 'MSG_COUNT_NOBODY',
           'MSG_TICK', 'MSG_FAILED', 'TEST_CMDS', 'TEST_ADMINS', 'TEST_SPOT', 'TEST_NEAR']:
    configDefaults[_k] = globals()[_k]

class TexMine( object ):

    def __init__( self, modManager ):
        self.mm = modManager
        self.__state = 0

    def init( self ):
        if 0 != self.__state:
            return
        cfg = self.mm.getModuleConfig( configDefaults )
        g = globals()
        for k in configDefaults:
            try:
                g[k] = cfg[k]
            except:
                pass
        self.__state = 1
        texmine_init()
        try:
            self.mm.info( 'texmine %s is running on mm_flbus (see %s)' % ( VERSION, LOG_FILE or 'no log' ) )
        except:
            pass

    def shutdown( self ):
        self.__state = 2
        S['on'] = 0
        if F is not None:
            F.active = 0
            F.look = None

    def update( self ):
        pass

def mm_load( modManager ):
    return TexMine( modManager )